    "code": "# ============================================================\n# Caesar cipher , cookbook #14\n# you already know: ROT13 via str.translate / a substitution map\n# teaches: building translation tables from parallel strings, has()-first\n#          map access, case handling without char codes, char walk via slice\n# run: operon run examples/cookbook/caesar.op\n# expected output: examples/cookbook/expected/caesar.out\n# verified by scripts/cookbook.sh on the Rust core AND the Python oracle\n# ============================================================\ngene shift_table(alphabet, places) {\n    # build alphabet -> shifted-alphabet as a map, no char codes needed\n    let cut = places % len(alphabet)\n    let rotated = alphabet.slice(cut, len(alphabet)) + alphabet.slice(0, cut)\n    let table = {}\n    for i in range(0, len(alphabet)) {\n        table[alphabet.slice(i, i + 1)] = rotated.slice(i, i + 1)\n    }\n    return table\n}\n\ngene substitute(text, table) {\n    let out = \"\"\n    for i in range(0, len(text)) {\n        let ch = text.slice(i, i + 1)\n        if has(table, ch) {\n            out = out + table[ch]\n        } else {\n            out = out + ch          # spaces and punctuation pass through\n        }\n    }\n    return out\n}\n\ngene main() {\n    let lower = \"abcdefghijklmnopqrstuvwxyz\"\n    let upper = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n\n    # encode uses the shifted tables (lower and upper need separate maps);\n    # decode is the same machine shifted back 26 - 3 = 23 places\n    let message = \"Attack At Dawn\"\n    let both = {}\n    let enc_lower = shift_table(lower, 3)\n    let enc_upper = shift_table(upper, 3)\n    for k in keys(enc_lower) { both[k] = enc_lower[k] }\n    for k in keys(enc_upper) { both[k] = enc_upper[k] }\n\n    let cipher = substitute(message, both)\n    promote(\"plain:  {message}\")\n    promote(\"cipher: {cipher}\")\n\n    # decode: shift back by 3 (26 - 3 = 23)\n    let back = {}\n    let dec_lower = shift_table(lower, 23)\n    let dec_upper = shift_table(upper, 23)\n    for k in keys(dec_lower) { back[k] = dec_lower[k] }\n    for k in keys(dec_upper) { back[k] = dec_upper[k] }\n    promote(\"round trip: {substitute(cipher, back)}\")\n\n    # rot13 is just caesar with a half turn\n    let rot13 = {}\n    let l13 = shift_table(lower, 13)\n    let u13 = shift_table(upper, 13)\n    for k in keys(l13) { rot13[k] = l13[k] }\n    for k in keys(u13) { rot13[k] = u13[k] }\n    promote(\"rot13 of \\\"{message}\\\": {substitute(message, rot13)}\")\n}\n",
