    "teaches": "the edge try_* family in one small machine \u2014 try_num",
    "code": "# ============================================================\n# Edge stack , cookbook #22\n# you already know: Pop() on an empty stack, index bounds checks\n# teaches: the edge try_* family in one small machine \u2014 try_num\n#          (tokens), try_get (map), try_pop/try_index (list),\n#          try_first/try_last (sequences) \u2014 every expected failure\n#          is an Err VALUE, so the machine keeps running\n# run: operon run examples/cookbook/edge_stack.op\n# expected output: examples/cookbook/expected/edge_stack.out\n# verified by scripts/cookbook.sh on the Rust core AND the Python oracle\n# ============================================================\n# A stack machine driven by a \"script\" of tokens. Bad tokens, bad\n# lookups, pops on empty \u2014 all just Err values the loop reports.\n# ops: push <n> | add | dup | total\nuse std/strings as s\nlet ops = { \"push\": 1, \"add\": 2, \"dup\": 3, \"total\": 4 }\ngene step(stack, line) {\n    let words = s.words(line)\n    let head = try_first(words)\n    if (is_err(head)) {\n        return err(\"blank line\")\n    }\n    let op = try_get(ops, unwrap(head))\n    if (is_err(op)) {\n        return err(\"unknown op '\" + unwrap(head) + \"'\")\n    }\n    match unwrap(op) {\n        case 1 {\n            let n = try_num(unwrap_or(try_index(words, 1), \"\"))\n            if (is_err(n)) {\n                return err(\"push needs a number\")\n            }\n            push(stack, unwrap(n))\n        }\n        case 2 {\n            let a = try_pop(stack)\n            if (is_err(a)) {\n                return err(\"add on empty stack\")\n            }\n            let b = try_pop(stack)\n            if (is_err(b)) {\n                push(stack, unwrap(a))\n                return err(\"add needs two operands\")\n            }\n            push(stack, unwrap(a) + unwrap(b))\n        }\n        case 3 {\n            let top = try_last(stack)\n            if (is_err(top)) {\n                return err(\"dup on empty stack\")\n            }\n            push(stack, unwrap(top))\n        }\n        case 4 {\n            let t = 0\n            for v in stack {\n                t = t + v\n            }\n            print(\"total=\" + str(t))\n        }\n    }\n    return ok(len(stack))\n}\nlet stack = []\nlet script = [\n    \"push 10\", \"push 32\", \"add\", \"total\", \"dup\",\n    \"push x\", \"add\", \"total\", \"divide\", \"\"\n]\nfor line in script {\n    match step(stack, line) {\n        case Ok(depth) {\n            print(\"depth=\" + str(depth))\n        }\n        case Err(why) {\n            print(\"ERR \" + why)\n        }\n    }\n}\nprint(\"final depth=\" + str(len(stack)) + \" first=\" + str(unwrap_or(try_first(stack), -1)))\n",
