    "name": "json_transform",
    "title": "json_transform",
    "teaches": "std/json dot-path navigation, merge/pick/omit, flatten,",
    "code": "# ============================================================\n# JSON transform , cookbook #03\n# you already know: json.loads + dict navigation + dict | overrides\n# teaches: std/json dot-path navigation, merge/pick/omit, flatten,\n#          and the chr(123)/chr(125) idiom for literal braces\n#          (a bare { in a string starts interpolation, gotcha!)\n# run: operon run examples/cookbook/json_transform.op\n# expected output: examples/cookbook/expected/json_transform.out\n# verified by scripts/cookbook.sh on the Rust core AND the Python oracle\n# ============================================================\nuse std/json as js\n\ngene main() {\n    # build JSON text without literal braces: [LB]/[RB] become { } below\n    let pieces = [\n        \"[LB]\\\"service\\\":\\\"api\\\",\\\"version\\\":2,\",\n        \"\\\"limits\\\":[LB]\\\"cpu\\\":4,\\\"mem\\\":8[RB],\",\n        \"\\\"tags\\\":[\\\"edge\\\",\\\"core\\\"],\\\"secret\\\":\\\"hunter2\\\"[RB]\"\n    ]\n    let src = pieces.join(\"\")\n    let cfg = json_parse(src.replace(\"[LB]\", chr(123)).replace(\"[RB]\", chr(125)))\n\n    # dot-path navigation: object steps by key, array steps by index\n    promote(\"service = {js.json_get(cfg, \"service\")}\")\n    promote(\"limits.cpu = {js.json_get(cfg, \"limits.cpu\")}\")\n    promote(\"tags.0 = {js.json_get(cfg, \"tags.0\")}\")\n    promote(\"missing = {js.json_get(cfg, \"limits.gpu\")}\")\n\n    # shallow merge, right side wins (same brace-free construction)\n    let ovr_text = \"[LB]\\\"version\\\":3,\\\"region\\\":\\\"eu\\\"[RB]\".replace(\"[LB]\", chr(123)).replace(\"[RB]\", chr(125))\n    let overrides = json_parse(ovr_text)\n    let merged = js.json_merge(cfg, overrides)\n    promote(\"merged version = {merged[\"version\"]}, region = {merged[\"region\"]}\")\n\n    # reshape: keep only what the API may see\n    let public = js.json_omit(merged, [\"secret\"])\n    promote(\"public has secret? {has(public, \"secret\")}\")\n\n    # flatten to dot-path scalars and count them\n    let flat = js.json_flatten(public)\n    promote(\"flat keys = {len(keys(flat))}\")\n    promote(\"flat.limits.mem = {flat[\"limits.mem\"]}\")\n\n    # parse + re-serialize drops formatting whitespace\n    promote(\"compact = {js.json_compact(json_str(public))}\")\n}\n",
