    "name": "log_sieve",
    "title": "log_sieve",
    "teaches": "try_re_groups \u2014 captures arrive as an Ok(list), a non-match",
    "code": "# ============================================================\n# Log sieve , cookbook #21\n# you already know: regex capture groups + guarded string slicing\n# teaches: try_re_groups \u2014 captures arrive as an Ok(list), a non-match\n#          is the fixed Err \"no match\" \u2014 and try_char_at for positional\n#          reads that refuse out-of-range as a value instead of a stress\n# run: operon run examples/cookbook/log_sieve.op\n# expected output: examples/cookbook/expected/log_sieve.out\n# verified by scripts/cookbook.sh on the Rust core AND the Python oracle\n# ============================================================\n# Sieve a batch of pipeline log lines: pull out the level, the stage and\n# the duration, and total the durations of the slow stages. Unmatched\n# lines are counted, never crashed on.\n#\n#   line shape: \"stage=BUILD level=WARN msg=elapsed=42ms\"\n#\nlet lines = [\n    \"stage=BUILD level=INFO msg=elapsed=12ms\",\n    \"stage=TEST level=WARN msg=elapsed=95ms\",\n    \"stage=DEPLOY level=INFO msg=elapsed=7ms\",\n    \"stage=free text nobody can parse\",\n    \"stage=LINT level=INFO msg=elapsed=3ms\"\n]\n# two capture groups: the stage token and the integer before \"ms\"\nlet pattern = \"stage=([A-Z]+) .*elapsed=([0-9]+)ms\"\nlet slow_total = 0\nlet slow_count = 0\nlet unmatched = 0\nfor line in lines {\n    let m = try_re_groups(pattern, line)\n    if (is_err(m)) {\n        unmatched = unmatched + 1\n    } else {\n        match m {\n            case Ok(groups) {\n                # groups[0] = stage, groups[1] = duration digits\n                let stage = groups[0]\n                let ms = try_num(groups[1])\n                # every parsed line has digits here, so assert the Ok path\n                let dur = unwrap_or(ms, 0)\n                if (dur > 50) {\n                    slow_total = slow_total + dur\n                    slow_count = slow_count + 1\n                    print(\"SLOW \" + stage + \" \" + str(dur) + \"ms\")\n                }\n            }\n            case Err(e) {\n                # unreachable: is_err was checked above; shown for the shape\n                print(\"impossible: \" + e)\n            }\n        }\n    }\n}\nprint(\"unmatched \" + str(unmatched))\nprint(\"slow \" + str(slow_count) + \" totalling \" + str(slow_total) + \"ms\")\n# try_char_at: peek the level column of the second line without slicing\n# by hand; index -1 reads from the end, out-of-range is a fixed Err\nlet second = lines[1]\nprint(\"col0=\" + unwrap_or(try_char_at(second, 0), \"?\"))\nprint(\"last=\" + unwrap_or(try_char_at(second, -1), \"?\"))\nlet past = try_char_at(second, 500)\nmatch past {\n    case Err(msg) {\n        print(\"range=\" + msg)\n    }\n    case Ok(c) {\n        print(\"range=\" + c)\n    }\n}\n",
    "verified": false,
    "expected": "SLOW TEST 95ms\nunmatched 1\nslow 1 totalling 95ms\ncol0=s\nlast=s\nrange=char_at index 500 out of range for string of length 38"
