    "name": "matrix_ops",
    "title": "matrix_ops",
    "teaches": "2D data as lists of lists, accumulator loops, row printing",
    "code": "# ============================================================\n# Matrix operations , cookbook #11\n# you already know: nested lists + a triple loop matmul\n# teaches: 2D data as lists of lists, accumulator loops, row printing\n#          with join\n# run: operon run examples/cookbook/matrix_ops.op\n# expected output: examples/cookbook/expected/matrix_ops.out\n# verified by scripts/cookbook.sh on the Rust core AND the Python oracle\n# ============================================================\ngene transpose(a) {\n    # a is rows x cols; out is cols x rows\n    let out = []\n    for j in range(0, len(a[0])) {\n        let col = []\n        for row in a {\n            push(col, row[j])\n        }\n        push(out, col)\n    }\n    return out\n}\n\ngene matmul(a, b) {\n    # a is r x k, b must be k x c; dot product of rows x transposed-cols\n    let bt = transpose(b)\n    let out = []\n    for row in a {\n        let new_row = []\n        for col in bt {\n            let acc = 0\n            for i in range(0, len(col)) {\n                acc += row[i] * col[i]\n            }\n            push(new_row, acc)\n        }\n        push(out, new_row)\n    }\n    return out\n}\n\ngene det2(a) {\n    return a[0][0] * a[1][1] - a[0][1] * a[1][0]\n}\n\ngene show_matrix(label, mat) {\n    promote(\"{label}:\")\n    for row in mat {\n        promote(\"  [{row.join(\" \")}]\")\n    }\n}\n\ngene main() {\n    let a = [[1, 2, 3], [4, 5, 6]]       # 2 x 3\n    let b = [[7, 8], [9, 10], [11, 12]]  # 3 x 2\n\n    show_matrix(\"a\", a)\n    show_matrix(\"a transposed\", transpose(a))\n    show_matrix(\"a x b\", matmul(a, b))\n\n    let sq = [[3, 8], [4, 6]]\n    show_matrix(\"sq\", sq)\n    promote(\"det(sq) = {det2(sq)}\")\n}\n",
