    "name": "monte_carlo_pi",
    "title": "monte_carlo_pi",
    "teaches": "a deterministic LCG (no wall clock, same output every",
    "code": "# ============================================================\n# Monte Carlo pi , cookbook #06\n# you already know: random.random() sampling on the unit square\n# teaches: a deterministic LCG (no wall clock, same output every\n#          run, on every core), float math, std/fmt formatting\n# run: operon run examples/cookbook/monte_carlo_pi.op\n# expected output: examples/cookbook/expected/monte_carlo_pi.out\n# verified by scripts/cookbook.sh on the Rust core AND the Python oracle\n# ============================================================\nuse std/fmt as fm\n\ngene lcg(seed) {\n    # classic glibc-flavoured LCG; fits i64 with no overflow\n    return (seed * 1103515245 + 12345) % 2147483648\n}\n\ngene main() {\n    let n = 10000\n    let state = 42\n    let hits = 0\n\n    for i in range(0, n) {\n        # map the raw integer into [-1, 1) for x and y\n        state = lcg(state)\n        let x = state / 1073741824.0 - 1.0\n        state = lcg(state)\n        let y = state / 1073741824.0 - 1.0\n        if x * x + y * y <= 1.0 {\n            hits += 1\n        }\n    }\n\n    let pi = 4.0 * hits / n\n    promote(\"points: {n}  inside circle: {hits}\")\n    promote(\"estimate: pi ~= {fm.fmt_fixed(pi, 4)}\")\n}\n",
