    "code": "# ============================================================\n# Word frequency , cookbook #01\n# you already know: collections.Counter(text.split()).most_common(3)\n# teaches: maps as counters, keys() iteration, sort_by_key with a\n#          gene (lambda) key, pad_left for aligned columns\n# run: operon run examples/cookbook/word_freq.op\n# expected output: examples/cookbook/expected/word_freq.out\n# verified by scripts/cookbook.sh on the Rust core AND the Python oracle\n# ============================================================\nuse std/iter as it\nuse std/strings as st\n\ngene count_words(text) {\n    # a map is insertion-ordered, so first-seen order is stable\n    let counts = {}\n    for w in st.words(text) {\n        if not has(counts, w) {\n            counts[w] = 0\n        }\n        counts[w] = counts[w] + 1\n    }\n    return counts\n}\n\ngene main() {\n    let text = \"the quick fox outruns the lazy dog the fox naps and the dog dreams the dog end\"\n    let counts = count_words(text)\n\n    # rank words by count, descending: sort ascending on (0 - count)\n    let ranked = it.sort_by_key(keys(counts), gene (w) {\n        return 0 - counts[w]\n    })\n    let top3 = it.take(ranked, 3)\n\n    let distinct = len(keys(counts))\n    promote(\"top words (of {distinct} distinct):\")\n    let rank = 1\n    for w in top3 {\n        let pos = st.pad_left(str(rank), 2, \" \")\n        let name = st.pad_right(w, 8, \".\")\n        promote(\"{pos}. {name} {counts[w]}\")\n        rank += 1\n    }\n\n    # counts map is reusable: how often does one word appear?\n    promote(\"fox appears {counts[\"fox\"]} times, dog appears {counts[\"dog\"]} times\")\n}\n",
