    "code": "# cookbook/wordcount \u2014 the classic, with std/strings + std/iter\n#\n# Count word frequencies in a paragraph and show the top 3.\n# `sort_by_key` \u2248 sort with a computed key; `fold` \u2248 reduce.\n#\n# Run:  operon run examples/cookbook/wordcount.op\n#\n# --- expected output ---\n# 1. operon (2)\n# 2. the (2)\n# 3. language (1)\n# distinct words: 8\n# ----------------------\n\nuse std/strings as st\nuse std/iter as it\nuse std/collections as col\n\nmain {\n    let text = \"the operon language reads like the lab notebook of a language designer operon keeps the metaphors honest\"\n\n    # words() splits on whitespace and drops empties\n    let ws = st.words(text)\n\n    # frequency map: fold a map up from the word list\n    let freq = it.fold(ws, {}, gene (acc, w) {\n        let c = 0\n        if has(acc, w) {\n            c = acc[w]\n        }\n        acc[w] = c + 1\n        return acc\n    })\n\n    # top 3 by count, ties broken by word for determinism\n    let pairs = it.map(keys(freq), gene (k) {\n        return [freq[k], k]\n    })\n    let ranked = pairs.sort(gene (a, b) {\n        if a[0] == b[0] {\n            return a[1] < b[1]\n        }\n        return a[0] > b[0]\n    })\n\n    let top = it.take(ranked, 3)\n    let i = 1\n    for p in top {\n        promote(\"{i}. {p[1]} ({p[0]})\")\n        i = i + 1\n    }\n    promote(\"distinct words: {len(freq)}\")\n    let _ = col.count([1], gene (x) => true)\n}\n",
